import{_ as t,o,c as a,a0 as n}from"./chunks/framework.ysVzM4be.js";const p=JSON.parse('{"title":"ADR 0033: Goto is navigation in both sections","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0033-goto-is-navigation-in-both-sections.md","filePath":"adr/0033-goto-is-navigation-in-both-sections.md"}'),i={name:"adr/0033-goto-is-navigation-in-both-sections.md"};function s(r,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0033-goto-is-navigation-in-both-sections" tabindex="-1">ADR 0033: Goto is navigation in both sections <a class="header-anchor" href="#adr-0033-goto-is-navigation-in-both-sections" aria-label="Permalink to &quot;ADR 0033: Goto is navigation in both sections&quot;">​</a></h1><p>Status: accepted Date: 2026-09-18</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0025 gave the Consultation its base-mode Goto, key <code>g</code>: it runs <code>herdr agent focus</code> on the agent&#39;s pane, reports on the Message line, and changes no Consultation state. &quot;It is navigation, not a decision.&quot;</p><p>The Ticket side kept Goto one level deeper: a row of the Live view and of the Decision modal, behind Enter. And the Ticket&#39;s Goto was not pure navigation: it also moved an <code>awaiting</code> ticket back to <code>running</code>, a state move the trace does not record. The state line already moves <code>awaiting -&gt; running</code> when the poll sees the agent working again on its still-pending turn, so the explicit move was not load-bearing. What it did leave was two Goto behaviors in the plane, and a key the Ticket section did not answer.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Key <code>g</code> is a base-mode control of the Ticket section, in both Ticket base modes.</strong> It is available on an in-flight ticket whose agent is alive in the last poll, and on an <code>awaiting</code> ticket whose handoff recorded a pane. It refuses elsewhere with the Consultation&#39;s own words: no agent is running on an <code>open</code> ticket, and the agent&#39;s pane is not alive in the last poll when the observation says it is gone.</p><p><strong>Every Goto in the plane is navigation.</strong> The base-mode control runs the same focus the modal rows run and reports the same confirmation, naming the workspace when herdr has one. The Goto rows of the Decision modal and the Live view drop the state move: the ticket stays where it is, <code>awaiting</code> until the poll moves it or the operator decides, in flight while it is in flight. The trace stays pending exactly as before, because a Goto was never a completion decision.</p><p>The considered alternatives:</p><ul><li>Keep the modal Goto&#39;s state move and give the base-mode key the same behavior. Rejected: an idle, settled agent would read <code>running</code> for as long as the operator watches it, and one control would mean two things depending on where the operator pressed it.</li><li>Make the Ticket Goto available on in-flight tickets only. Rejected: <code>awaiting</code> is exactly when the operator wants to look at the agent - the turn just settled - and the modal row already worked there.</li><li>Leave the Ticket Goto in the modals and accept the asymmetry. Rejected: it is the asymmetry the operator asked to close, and the Consultation proof of the shape (ADR 0025) already stands.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Goto is one key and one meaning in both sections: focus the agent&#39;s pane, change no record. The Action bar and the Key guide state it from the catalogue, in every mode it runs on.</li><li>After a Goto from the Decision modal, the ticket reads <code>awaiting</code> until the agent works again. The badge is still true: the decision is pending, and the operator went to look, not to decide.</li><li>The refusal wording is shared with the Consultation, so a key the operator learned in one section refuses readably in the other.</li><li>The Live view and the Decision modal keep their Goto rows: the rows are the decision surfaces&#39; own way to the pane, and the base-mode key is the way that does not open a surface.</li></ul>',12)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
